begin;

set constraints all immediate;

update seasons set is_active = false where is_active = true and deleted_at is null;

insert into seasons (id, code, title, starts_on, ends_on, status, is_active)
values ('9c077ea6-611d-519e-bf0b-fae9b0c6d2f5'::uuid, 'IELTSBRO-2026-05-08', '雅思哥口语题库 2026年5-8月', '2026-05-01'::date, '2026-08-31'::date, 'active', true)
on conflict (code) do update set
    title = excluded.title,
    starts_on = excluded.starts_on,
    ends_on = excluded.ends_on,
    status = 'active',
    is_active = true,
    updated_at = now(),
    deleted_at = null;

update questions
set review_status = 'archived', updated_at = now()
where season_id = '9c077ea6-611d-519e-bf0b-fae9b0c6d2f5'::uuid
  and deleted_at is null
  and metadata->>'source' = 'ieltsbro'
  and metadata->>'coverage' = 'first_public_question_only';

update knowledge_docs kd
set status = 'archived', updated_at = now()
from questions q
where kd.source_id = q.id
  and kd.doc_type = 'question_bank'
  and kd.deleted_at is null
  and q.season_id = '9c077ea6-611d-519e-bf0b-fae9b0c6d2f5'::uuid
  and q.metadata->>'source' = 'ieltsbro'
  and q.metadata->>'coverage' = 'first_public_question_only';

update topics t
set status = 'archived',
    deleted_at = coalesce(t.deleted_at, now()),
    updated_at = now()
where t.deleted_at is null
  and t.status = 'active'
  and (t.slug like 'ieltsbro-p1-%' or t.slug like 'ieltsbro-p23-%')
  and not exists (
      select 1
      from questions q
      where q.topic_id = t.id
        and q.deleted_at is null
        and q.review_status = 'active'
  );

insert into topic_categories (id, name, slug)
values ('b7c3f061-0d0e-59e9-9009-595399cd4c6a'::uuid, '大陆地区 万年老题', 'ieltsbro-pdf-mainland-evergreen')
on conflict (slug) do update set
